package it.frociart.app;
import java.io.*;import java.nio.channels.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class CodeTemplateStoreTests {
 interface Action{void run()throws Exception;}static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}static void reject(Action action,String why)throws Exception{try{action.run();}catch(IOException|IllegalArgumentException ex){checks++;return;}throw new AssertionError("Expected rejection: "+why);}
 static FlowCodeTemplate t(String name){return FlowCodeTemplate.create(name,"python","py","Python 3","# {{ project.title | literal }}\n{{ source }}");}
 public static void main(String[] args)throws Exception{Path folder=Paths.get(args[0]).resolve("store-tests").resolve("android-"+FlowTemplateStore.newId());FlowTemplateStore store=new FlowTemplateStore(folder.toFile());check(store.entries().isEmpty()&&!Files.exists(folder),"Read absent library does not create storage");String emptyId=FlowTemplateStore.newId();Files.createDirectories(folder.resolve(emptyId));for(int e=0;e<35;e++)Files.createDirectories(folder.resolve(FlowTemplateStore.newId()));check(store.entries().isEmpty(),"Empty directories never appear as phantom models or consume capacity");String id=FlowTemplateStore.newId(),draft="bozza non valida {{";store.saveDraft(id,draft);FlowTemplateStore.Entry entry=store.load(id);check(entry.raw==null&&entry.draft.equals(draft)&&store.entries().size()==1,"Unsaved draft survives reopening");entry=store.save(id,t("Python personale").text,null);check(entry.definition.text.equals(t("Python personale").text)&&entry.fingerprint!=null&&entry.draft.equals(draft),"Real save preserves unfinished draft");check(!store.clearDraft(id,"obsolete")&&store.load(id).draft.equals(draft),"Stale completion cannot discard newer draft");check(store.clearDraft(id,draft)&&store.load(id).draft==null,"Matching draft clear");
  String fingerprint=entry.fingerprint;reject(()->store.save(id,t("Python personale").text.replace("{{ source }}","{% if true %}"),fingerprint),"Invalid template never replaces saved one");check(store.load(id).fingerprint.equals(fingerprint),"Invalid save preserves bytes");FlowTemplateStore other=new FlowTemplateStore(folder.toFile());entry=other.save(id,t("Aggiornato").text,fingerprint);final String current=entry.fingerprint;reject(()->store.save(id,t("Python personale").text,fingerprint),"Revision guard across instances");check(store.load(id).fingerprint.equals(current),"Conflict preserves newer version");String second=FlowTemplateStore.newId();reject(()->store.save(second,t("Aggiornato").text,null),"Duplicate names");check(!Files.exists(folder.resolve(second)),"Rejected new model creates no entry directory");
  try(FileChannel channel=FileChannel.open(folder.resolve(".lock"),StandardOpenOption.WRITE);FileLock lock=channel.lock()){reject(()->store.saveDraft(id,"new draft"),"Actual exclusive lock prevents second writer");}check(store.load(id).draft==null,"Busy archive retains prior state");
  store.saveDraft(id,"editing");store.archive(id,current);check(store.entries().isEmpty()&&store.entries(true).get(0).draft.equals("editing"),"Archive retains main/draft");store.restore(id);check(store.load(id).fingerprint.equals(current)&&store.load(id).draft.equals("editing")&&store.entries(true).isEmpty(),"Restore preserves main and draft");Path extra=folder.resolve(id).resolve("outside.txt");Files.write(extra,"OWNED FIXTURE".getBytes(StandardCharsets.UTF_8));reject(()->store.archive(id,current),"Unknown files never moved/deleted");check(new String(Files.readAllBytes(extra),StandardCharsets.UTF_8).equals("OWNED FIXTURE")&&store.entries().size()==1,"Unknown file retained");Files.delete(extra);
  Path export=folder.resolve("external.frotemplate");FlowTemplateStore.export(export.toFile(),entry.definition);check(FlowCodeTemplate.parse(FlowTemplateStore.readImport(export.toFile())).text.equals(entry.definition.text),"Actual UTF8 export/import");Files.write(export,"ORIGINAL".getBytes(StandardCharsets.UTF_8));FlowTemplateStore.export(export.toFile(),t("Export nuovo"));check(new String(Files.readAllBytes(export),StandardCharsets.UTF_8).equals(t("Export nuovo").text),"Actual replacement");Files.write(export,new byte[]{(byte)255,0,(byte)255});reject(()->FlowTemplateStore.readImport(export.toFile()),"Malformed UTF8 import");reject(()->store.saveDraft("../outside","payload"),"Traversal identifier");reject(()->store.saveDraft(id,"\ud800"),"Incomplete Unicode draft");check(store.load(id).draft.equals("editing"),"Bad Unicode preserves draft");
  store.archive(id,current);store.deleteArchived(id);check(store.entries().isEmpty()&&store.entries(true).isEmpty()&&!Files.exists(folder.resolve("archive").resolve(id)),"Explicit permanent delete only archived entry");for(int i=0;i<FlowTemplateStore.MAX_ENTRIES;i++)store.save(FlowTemplateStore.newId(),t("Modello "+i).text,null);reject(()->store.saveDraft(FlowTemplateStore.newId(),"new"),"Entry count bound");reject(()->store.saveDraft(emptyId,"new"),"Existing empty directory cannot bypass model count limit");check(store.entries().size()==FlowTemplateStore.MAX_ENTRIES,"Entry limit preserves all earlier data");String corrupt=store.entries().get(0).id;Path main=folder.resolve(corrupt).resolve("definition.frotemplate");Files.write(main,new byte[FlowCodeTemplate.MAX_BYTES+1]);FlowTemplateStore.Entry broken=store.load(corrupt);check(broken.problem!=null&&broken.fingerprint==null,"Oversized saved file is recoverable problem");reject(()->store.save(corrupt,t("Corretto").text,null),"Unreadable saved file cannot be mistaken for absent");check(Files.size(main)==FlowCodeTemplate.MAX_BYTES+1,"Read failure preserves original bytes");try(java.util.stream.Stream<Path> files=Files.walk(folder)){check(!files.anyMatch(path->path.getFileName().toString().startsWith(".pending-")),"No pending temp files");}
  FlowTemplateDraft form=new FlowTemplateDraft("", "python","","incompleto 🐢","{% if true %}\n0\n\n🐢",false);FlowTemplateDraft restored=FlowTemplateDraft.decode(form.encode());check(restored.name.equals(form.name)&&restored.body.equals(form.body)&&restored.instructions.equals(form.instructions)&&!restored.caseSensitive,"Unfinished form codec preserves Unicode, empty metadata and invalid syntax");check(new String(Files.readAllBytes(Paths.get(args[0]).resolve("draft-example.txt")),StandardCharsets.UTF_8).equals(form.encode()),"PC and Android draft format is byte-identical");reject(()->FlowTemplateDraft.decode(form.encode()+"trailing"),"Trailing draft garbage");reject(()->FlowTemplateDraft.decode("FrociartTemplateDraft1\n999999\nshort"),"Truncated draft");
  System.out.println("TEMPLATE_STORE_ANDROID PASS checks="+checks);
 }
}
